export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedAcceleration = -gravity;

  const dropHeld = t < apexTime;
  const dropTime = dropHeld ? 0 : (t - apexTime);
  const dropVelocity = dropHeld ? 0 : (-gravity * dropTime);
  const dropHeight = dropHeld ? apexHeight : (apexHeight - 0.5 * gravity * dropTime * dropTime);
  const dropAcceleration = dropHeld ? 0 : -gravity;

  const maxH = 2.2;
  const frameH = 420;
  const frameW = 640;

  const scaleY = (h) => frameH - 60 - (h / maxH) * 280;

  const tossX = 180;
  const dropX = 460;
  const laneW = 240;
  const laneH = 340;
  const laneY = 50;

  const tossY_px = scaleY(tossedHeight);
  const dropY_px = scaleY(dropHeight);

  let tossState = "Rising";
  if (t < 0.05) tossState = "At launch";
  else if (Math.abs(t - apexTime) < 0.05) tossState = "At the top";
  else if (t > apexTime && tossedHeight > 0.05) tossState = "Falling";
  else if (t >= apexTime) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) < 0.05) dropState = "Just released";
  else if (t > apexTime && dropHeight > 0.05) dropState = "Falling together";
  else if (t >= apexTime) dropState = "At launch height";

  const objects = [];

  objects.push(...sdk.panel({ x: 60, y: laneY, w: laneW, h: laneH, title: "Toss", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: laneY, w: laneW, h: laneH, title: "Drop", state: dropState, id: "lane.drop" }));

  objects.push(sdk.axis("axis.toss", { x: tossX - 60, y: laneY + 40, length: 280, orientation: "y", min: 0, max: maxH, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: dropX - 60, y: laneY + 40, length: 280, orientation: "y", min: 0, max: maxH, ticks: [0, 0.5, 1.0, 1.5, 2.0], label: "Height", unit: "m" }));

  objects.push(sdk.circle("ball.toss", tossX, tossY_px, 24, { role: "output" }));
  objects.push(sdk.circle("ball.drop", dropX, dropY_px, 24, { role: "output" }));

  objects.push(...sdk.vector("vec.v.toss", { x: tossX - 25, y: tossY_px }, { value: tossedVelocity, direction: "up" }, { scale: 12, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + 25, y: tossY_px }, { value: tossedAcceleration, direction: "up" }, { scale: 6, label: "a" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX - 25, y: dropY_px }, { value: dropVelocity, direction: "up" }, { scale: 12, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + 25, y: dropY_px }, { value: dropAcceleration, direction: "up" }, { scale: 6, label: "a" }));

  const gateY_px = scaleY(apexHeight);
  objects.push(sdk.gate("gate", dropX, gateY_px, { open: !dropHeld, label: "Gate" }));

  objects.push(...sdk.callout(tossX + 45, tossY_px - 20, ["v: " + sdk.format(tossedVelocity) + " m/s", "a: " + sdk.format(tossedAcceleration) + " m/s^2"], { id: "callout.toss" }));
  objects.push(...sdk.callout(dropX + 45, dropY_px - 20, ["v: " + sdk.format(dropVelocity) + " m/s", "a: " + sdk.format(dropAcceleration) + " m/s^2"], { id: "callout.drop" }));

  return {
    frame: {
      width: frameW,
      height: frameH,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
